export class Rectangle {
    x;
    y;
    width;
    height;
    constructor(x = 0, y = 0, width = 0, height = 0) {
        this.x = x;
        this.y = y;
        this.width = width;
        this.height = height;
    }
    contains(x, y) { return x >= this.x && y >= this.y && x <= this.x + this.width && y <= this.y + this.height; }
}